import DOMPurify from 'isomorphic-dompurify';
import { Parser } from 'node-sql-parser';
import { z } from 'zod';

// 1. Zod Schema ép kiểu tuyệt đối cho hành động Agent (không chấp nhận trường lạ)
export const AgentActionSchema = z.discriminatedUnion('action', [
  z.object({
    action: z.literal('reply_markdown'),
    markdownHtml: z.string().max(8000),
    suggestedFollowUpUrl: z.string().url().optional(),
  }).strict(),
  z.object({
    action: z.literal('query_sales_kpi'),
    dateFrom: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
    dateTo: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
    agencyId: z.string().uuid().optional(),
  }).strict(),
]);

// 2. Làm sạch HTML/Markdown từ LLM: cấm script, iframe, img ngoài và link javascript:
export function sanitizeLlmRenderedHtml(rawHtmlFromMarkdown: string): string {
  const clean = DOMPurify.sanitize(rawHtmlFromMarkdown, {
    ALLOWED_TAGS: ['p', 'br', 'strong', 'em', 'ul', 'ol', 'li', 'code', 'pre', 'table', 'thead', 'tbody', 'tr', 'th', 'td', 'a'],
    ALLOWED_ATTR: ['href', 'title', 'rel', 'target'],
    ALLOW_DATA_ATTR: false,
    FORBID_TAGS: ['img', 'svg', 'iframe', 'object', 'script', 'style', 'form'],
  });

  // Kiểm tra lại giao thức href phòng trường hợp lách qua encoding
  return clean.replace(/href\s*=\s*"([^"]*)"/gi, (_match, url: string) => {
    try {
      const parsed = new URL(url, 'https://domation.net');
      if (parsed.protocol === 'https:' || parsed.protocol === 'mailto:') {
        return `href="${parsed.href}" rel="noopener noreferrer nofollow" target="_blank"`;
      }
    } catch {
      // URL hỏng -> vô hiệu hóa
    }
    return 'href="#blocked-unsafe-url"';
  });
}

// 3. Kiểm định AST cho Text-to-SQL: chỉ cho phép 1 câu SELECT trên bảng whitelist
const sqlParser = new Parser();
const ALLOWED_BI_TABLES = new Set(['vw_crm_pipeline_summary', 'vw_lead_attribution_daily']);

export function assertSafeReadOnlyBiSql(llmGeneratedSql: string): string {
  const ast = sqlParser.astify(llmGeneratedSql, { database: 'Postgresql' });
  const statements = Array.isArray(ast) ? ast : [ast];
  if (statements.length !== 1 || statements[0].type !== 'select') {
    throw new Error('[LLM05_SQL_BLOCK] Chỉ cho phép đúng 1 câu lệnh SELECT duy nhất.');
  }
  const tableList = sqlParser.tableList(llmGeneratedSql, { database: 'Postgresql' });
  for (const entry of tableList) {
    // Định dạng trả về: "select::null::table_name"
    const tableName = entry.split('::').pop()?.toLowerCase() || '';
    if (!ALLOWED_BI_TABLES.has(tableName)) {
      throw new Error(`[LLM05_SQL_BLOCK] Bảng '${tableName}' không nằm trong danh sách BI View được cấp phép.`);
    }
  }
  return sqlParser.sqlify(statements[0], { database: 'Postgresql' });
}
